										</AsyncPreview.Trigger>
										<AsyncPreview.Content>
											<AsyncPreview.Loading />
											<AsyncPreview.Error />
											<AsyncPreview.Empty />
											<AsyncPreview.Body>
												{(data) => <CustomerCard customer={data as Customer} />}
											</AsyncPreview.Body>
										</AsyncPreview.Content>
									</AsyncPreview.Root>
								) : (
									<PreviewTriggerCell
										value={null}
										hasPreview={false}
										disabledReason={row.note}
									/>
								)}
							</TableCell>
							<TableCell>{row.reference}</TableCell>
						</TableRow>
					)
				})}
			</TableBody>
		</Table>
	)
}

